var n=`0652-superkanja`;var i=`world-0652`;var a=`GM`;var s=`western-africa`;var o=4;var r=46;var g={en:`Superkanja`,ua:`Суперканжа`};var l={en:`Superkanja is a Gambia classic prepared with yellow onion, tomato, scotch bonnet pepper, okra. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Суперканжа, страва кухні країни Гамбія зі складниками: жовта цибуля, помідор, перець скотч-боннет, бамія. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var d=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,150,`g`],[`red-palm-oil`,55,`ml`],[`tomato`,250,`g`],[`scotch-bonnet-pepper`,1,`pcs`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 32 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 32 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:32,i:[[`okra`,480,`g`],[`tilapia`,480,`g`],[`water`,630,`ml`],[`crayfish`,120,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`ground-cumin`,4,`g`],[`table-salt`,null,`to_taste`]]}];var u={slug:n,id:i,country:`GM`,region:s,servings:4,minutes:46,title:g,text:l,steps:d};export{a as country,u as default,i as id,r as minutes,s as region,o as servings,n as slug,d as steps,l as text,g as title};